; bios.asm -- chapter 21: the BIOS's four screen modes
; generated by gen21.py
        INCLUDE "msx.inc"
        OUTPUT "bios.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; INITXT, INIT32, INIGRP and INIMLT in turn. At r0 to r3 the debugger reads
; the VDP's registers and the BIOS's table addresses (TXTNAM to MLTPAT). Then
; CHGMOD with A = 0 to 3, read at m0 to m3.
init:   di
        ld sp, SYS_AREA
c0:     call INITXT
        di                      ; the BIOS leaves the interrupts on (chapter 16)
r0:     nop                     ; the debugger reads the registers here
c1:     call INIT32
        di                      ; the BIOS leaves the interrupts on (chapter 16)
r1:     nop                     ; the debugger reads the registers here
c2:     call INIGRP
        di                      ; the BIOS leaves the interrupts on (chapter 16)
r2:     nop                     ; the debugger reads the registers here
c3:     call INIMLT
        di                      ; the BIOS leaves the interrupts on (chapter 16)
r3:     nop                     ; the debugger reads the registers here
        ld a, 0
g0:     call CHGMOD             ; screen mode 0
        di
m0:     nop                     ; the registers again
        ld a, 1
g1:     call CHGMOD             ; screen mode 1
        di
m1:     nop                     ; the registers again
        ld a, 2
g2:     call CHGMOD             ; screen mode 2
        di
m2:     nop                     ; the registers again
        ld a, 3
g3:     call CHGMOD             ; screen mode 3
        di
m3:     nop                     ; the registers again
done:   jr done
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
